const e=[{id:"sv-5-1126",phase:5,topic:"5.2.10",qtype:"concept",difficulty:1,stem:"Besides detecting special-cause variation, what else does the book say SPC provides?",options:["A glimpse of ongoing process capability and a visual management tool","The root cause of each out-of-control signal","Proof that every unit meets the specification limits","A replacement for the response plan in the control plan"],answer:0,hint:"Recall the book's 'Purpose of SPC' slide.",steps:[{title:"Key idea",body:"The book: SPC gives a glimpse of ongoing process capability AND is a visual management tool; it detects special causes but does NOT say why."},{title:"Eliminate",body:"Root causes, spec conformance and the response plan are outside what SPC itself delivers."}],final:"Capability glimpse + visual management → answer **A**",whyWrong:["","Incorrect — the book stresses that SPC detects special causes but does NOT tell us why.","Incorrect — control limits are the voice of the process; they do not prove conformance to specs.","Incorrect — a signal still needs the OCAP and response plan; SPC does not replace them."],trap:"SPC says that something changed, never why.",bookRef:"Book p. 523"},{id:"sv-5-1127",phase:5,topic:"5.2.10",qtype:"concept",difficulty:1,stem:"On which SPC chart does the book say **specification limits** are plotted?",options:["CuSum chart","EWMA chart","Individuals chart","Pre-Control chart"],answer:3,hint:"Only one chart in the book is described as using limits relative to the specification.",steps:[{title:"Key idea",body:'Pre-Control is the "first and ONLY" SPC chart on which specification limits are plotted (green, yellow and red zones).'},{title:"Eliminate",body:"I, EWMA and CuSum charts all use statistically calculated limits — the voice of the process."}],final:"Pre-Control uses spec limits → answer **D**",whyWrong:["Incorrect — a CuSum chart plots cumulative deviations from a target against decision limits, not spec limits.","Incorrect — an EWMA chart uses limits calculated from process variation, not the customer's specification.","Incorrect — the book warns never to put spec limits on an Individuals chart; its limits are ±3σ from the data.",""],bookRef:"Book p. 543"},{id:"sv-5-1128",phase:5,topic:"5.2.10",qtype:"concept",difficulty:2,stem:"How is a process **qualified** with Pre-Control after a tool change or a new operator?",options:["By running five consecutive parts that all fall in the green zone","By plotting 25 subgroups and calculating limits at ±3σ","By sampling two consecutive parts that fall inside the specification","By checking that nine points in a row fall on one side of target"],answer:0,hint:"Qualifying and monitoring use different part counts in Pre-Control.",steps:[{title:"Key idea",body:"To qualify (or re-qualify) a process, **five consecutive parts** must fall in the green zone."},{title:"Apply",body:"Re-qualify after tool changes, adjustments, new operators or material changes; then monitor with two-part samples."}],final:"Qualify with five greens → answer **A**",whyWrong:["","Incorrect — 25 subgroups and ±3σ limits describe setting up a Shewhart control chart, not Pre-Control.","Incorrect — two consecutive parts is the ongoing monitoring sample, used only after the process is qualified.","Incorrect — nine in a row on one side is Test 2 for a shift on a control chart."],trap:"Five to qualify, two to monitor.",bookRef:"Book p. 543"},{id:"sv-5-1129",phase:5,topic:"5.2.10",qtype:"concept",difficulty:2,stem:"Which is a reason the book gives for **recalculating** control limits after a verified process change?",options:["To avoid false special-cause signals from out-of-date limits","To bring a point that is beyond the UCL back inside the limits","To make the control limits match the customer's specification","To reduce how often operators need to sample the process"],answer:0,hint:"Old limits on a changed process produce misleading signals.",steps:[{title:"Key idea",body:'The book: an incentive to recalculate limits is "avoiding false Special Cause detection" once variation is reduced or the process has shifted.'},{title:"Eliminate",body:"Hiding a signal, copying specs onto the chart and changing sampling frequency are not reasons for recalculation."}],final:"Recalculate to avoid false signals → answer **A**",whyWrong:["","Incorrect — recalculating to hide a signal is masking a special cause; the point needs the OCAP.","Incorrect — control limits are the voice of the process and must never be set to the spec limits.","Incorrect — sampling frequency is set in the monitoring plan, not by recalculating limits."],bookRef:"Book p. 553"},{id:"sv-5-1130",phase:5,topic:"5.2.10",qtype:"concept",difficulty:2,stem:"Which statement about recalculating control limits is CORRECT?",options:["Limits are recalculated each time a new point falls outside them","Limits are recalculated for variables charts but never for attribute charts","Limits are recalculated whenever the specification limits are changed","Limits are recalculated after a verified reduction in variation or a known shift"],answer:3,hint:"Limits follow evidence that the process itself has changed.",steps:[{title:"Key idea",body:"Reduction in variation or a known process shift should lead to recalculating the centre line and limits; confirm with a hypothesis test."},{title:"Apply",body:"Periodic reviews (3, 6 or 12 months) also help capture documented changes — for variables and attribute charts alike."}],final:"Recalculate after a verified change → answer **D**",whyWrong:["Incorrect — a point beyond a limit is a special cause to investigate with the OCAP, not a trigger to reset limits.","Incorrect — the book says its recalculation guidance applies to both variables and attribute data.","Incorrect — specification limits are the voice of the customer and do not drive control limits.",""],trap:"Changing the specs never changes the control limits.",bookRef:"Book p. 553"},{id:"sv-5-1131",phase:5,topic:"5.2.10",qtype:"statements",difficulty:3,stem:`Consider these statements about **Pre-Control**:

1. It is to be used only for the outputs of a process.
2. Its green zone lies between the two Pre-Control lines around the target.
3. Its limits are calculated at ±3σ from the process mean.
4. Two parts in the yellow zones on opposite sides call for a small adjustment.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Pre-Control works from the tolerance, not from process sigma.",steps:[{title:"Key idea",body:"Pre-Control is used ONLY for outputs; the green zone sits between the PC lines (the middle of the tolerance), yellow between PC lines and specs, red outside specs."},{title:"Apply",body:"Statements 1 and 2 are true. Limits are not ±3σ (3), and yellow on opposite sides means stop, not adjust (4)."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: Pre-Control zones are set relative to the specification limits, not ±3σ.","Incorrect — both are false: limits come from the specs, and yellow on opposite sides means stop the process.","Incorrect — statement 4 is false: yellow on opposite sides shows the process is out of control and must stop."],bookRef:"Book p. 543"},{id:"sv-5-1132",phase:5,topic:"5.2.10",qtype:"missing-word",difficulty:1,stem:`Identify the missing words in the following sentence.

SPC on X's or Y's without proper usage = [?].`,options:["Containment","Poka-yoke","Visual factory","Wall paper"],answer:3,hint:"The book's bottom row of the control-method ranking uses a household image.",steps:[{title:"Key idea",body:`The book ranks control methods and ends with "SPC on X's or Y's without proper usage = WALL PAPER".`},{title:"Apply",body:"Doing SPC just to say you do SPC wastes time and makes people reject the tool."}],final:"Misused SPC = wall paper → answer **D**",whyWrong:["Incorrect — containment (audits, 100% inspection) is the Type 3 corrective action, a genuine control level.","Incorrect — poka-yoke is the most effective control (Type 1 prevention, Type 2 detection), not misused SPC.","Incorrect — properly used SPC supports a visual factory; misused SPC is the opposite.",""],bookRef:"Book p. 522"},{id:"sv-5-1133",phase:5,topic:"5.2.10",qtype:"not-except",difficulty:2,stem:"For SPC on the X's to work as the **third most effective** control, which condition is NOT required by the book?",options:["Specification limits drawn on each control chart","Employees who are fully trained in the SPC rules","Employees who respect the rules once a chart signals","Management that empowers employees to take action"],answer:0,hint:"Think trained, respected, empowered — and what the book says never to put on a control chart.",steps:[{title:"Key idea",body:"SPC on X's is effective when employees are fully trained, respect the rules and are empowered by management to act."},{title:"Eliminate",body:"Spec limits are not a condition — the book advises never plotting them on a control chart."}],final:"Spec limits are not a condition → answer **A**",whyWrong:["","Incorrect — full training is one of the stated conditions for SPC on X's to be an effective control.","Incorrect — respecting the rules and agreeing to act on a signal is a stated condition.","Incorrect — empowerment by management is required; without it SPC drops to the inspection level."],trap:"Trained but not empowered staff push SPC down to the containment level.",bookRef:"Book p. 522"},{id:"sv-5-1134",phase:5,topic:"5.2.10",qtype:"scenario",difficulty:2,stem:'An I chart of **daily port-in failures** fails Test 1 on day 18. The supervisor asks the analyst to "read the cause off the chart" so it can go into the weekly report. Which reply is BEST?',options:["The point reflects common-cause variation, so no cause needs to be reported","The chart shows the cause was the agent on shift that day","The chart shows a special cause occurred; the OCAP and investigation must find why","The limits must be recalculated first so that the cause becomes visible"],answer:2,hint:"A signal says that, never why.",steps:[{title:"Key idea",body:"SPC detects special causes but does NOT tell us why."},{title:"Apply",body:"The next step is the OCAP: check the listed causes, correct, and record the action on the chart."}],final:"Detect with SPC, explain with the OCAP → answer **C**",whyWrong:["Incorrect — a Test 1 failure is a special-cause signal, not common-cause noise.","Incorrect — the chart records when a signal occurred, not who or what caused it.","","Incorrect — recalculating limits does not reveal causes and would only mask the signal."],bookRef:"Book pp. 523, 544"},{id:"sv-5-1135",phase:5,topic:"5.2.10",qtype:"scenario",difficulty:3,stem:"A crimp-height process is under Pre-Control. In a routine check of two consecutive parts, the **first** falls in the upper yellow zone and the **second** also falls in the upper yellow zone. What should the operator do?",options:["Continue running without any change","Stop production and find the reason","Re-qualify with five parts before checking","Make an adjustment to the process"],answer:3,hint:"One yellow → check the second part; where it lands decides the action.",steps:[{title:"Key idea",body:"Pre-Control rule: one part yellow → inspect the other. Green → continue; yellow on the **same** side → adjust; yellow on the opposite side or red → stop."},{title:"Apply",body:"Both parts are in the upper yellow zone (same side), so the operator adjusts the process."}],final:"Two yellows on the same side → adjust → answer **D**",whyWrong:["Incorrect — continue only if the second part had fallen in the green zone.","Incorrect — stop if the second part is in yellow on the opposite side or in red.","Incorrect — re-qualification follows tool changes, new operators or material changes, not this result.",""],trap:"Same side = adjust; opposite sides = stop.",bookRef:"Book p. 543"},{id:"sv-5-1136",phase:5,topic:"5.2.10",qtype:"best-action",difficulty:3,stem:"Six months after closure, the planned review of an I chart of **activation time** is due. No process change has been documented and the chart shows no failed tests. The process owner keeps the existing limits. Was this appropriate?",options:["Yes, because limits are recalculated only when performance has been shown to change","Yes, because control limits must never be changed once a project has closed","No, because the limits must be recalculated at every periodic review","No, because the limits should be replaced by the specification at review"],answer:0,hint:"A review checks the limits; evidence of change resets them.",steps:[{title:"Key idea",body:"Recalculate after reduced variation or a known shift, confirmed with a hypothesis test; periodic reviews (3, 6, 12 months) capture such changes."},{title:"Apply",body:"No documented change and no signals → keep the frozen historical limits."}],final:"Keep limits without evidence of change → answer **A**",whyWrong:["","Incorrect — the book says limits should be recalculated if process changes are documented after closure.","Incorrect — a periodic review is a check; it does not force a recalculation when nothing has changed.","Incorrect — spec limits never replace control limits on a Shewhart chart."],bookRef:"Book p. 553"},{id:"sv-5-1137",phase:5,topic:"5.2.10",qtype:"output",difficulty:3,stem:`A supervisor wants to reset the centre line of an I chart because the latest points "look lower". Before recalculating, the Belt compares 30 points before and 30 points after the suspected shift (α = 0.05):

\`\`\`
Two-Sample T-Test and CI: Before, After

         N    Mean   StDev
Before  30   12.40    1.10
After   30   12.21    1.05

Difference = μ (Before) - μ (After)
T-Test of difference = 0 (vs ≠): T-Value = 0.68  P-Value = 0.497  DF = 57
\`\`\`

Which decision is correct?`,options:["Fail to reject H₀; keep the existing centre line and limits","Reject H₀; recalculate the centre line and limits","Accept H₀; the means are proven equal, so recalculate","Fail to reject H₀; recalculate because the After mean is lower"],answer:0,hint:"p < α → reject H₀; limits change only on a verified shift.",steps:[{title:"Key idea",body:"The book: confirm a shift with a hypothesis test before recalculating the centre line and limits."},{title:"Apply",body:"P-Value = 0.497 > 0.05 → fail to reject H₀ → no verified shift → keep the limits."}],final:"p = 0.497 → no verified shift → keep limits → answer **A**",whyWrong:["","Incorrect — p = 0.497 is above 0.05, so there is no evidence of a shift to justify new limits.","Incorrect — we never 'accept' or prove H₀, and no shift means no recalculation.","Incorrect — a lower sample mean without a significant result is common-cause noise, not a verified shift."],bookRef:"Book p. 553"},{id:"sv-5-1138",phase:5,topic:"5.2.10",qtype:"sequence",difficulty:1,stem:`A point on an I chart fails Test 1. Put the book's response steps in order:

- **P** — Follow the OCAP to find and correct the cause
- **Q** — Record the action taken on the chart
- **R** — Recognise the out-of-control signal in real time
- **S** — Take the next sample and, if in control, make no further change`,options:["P, R, Q, S","R, P, Q, S","R, Q, P, S","R, P, S, Q"],answer:1,hint:"Detect → react → record → verify, without tampering.",steps:[{title:"Key idea",body:"Plot in real time, act with the OCAP, record actions taken; once back in control, do not make more changes."},{title:"Apply",body:"Signal (R) → OCAP (P) → record (Q) → next sample, no extra adjustment (S)."}],final:"R, P, Q, S → answer **B**",whyWrong:["Incorrect — the OCAP cannot be followed before the signal has been recognised.","","Incorrect — the action is recorded after it has been taken, not before the OCAP is followed.","Incorrect — the action is recorded straight after the correction, before judging the next sample."],bookRef:"Book pp. 544, 569"},{id:"sv-5-1139",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"What are the three criteria used to rate potential improvements in the **Improvement Selection Matrix**?",options:["Severity, occurrence and detection","Significance, correlation and capability","Impact, cost and time","Scope, schedule and budget"],answer:2,hint:"Recall the three considerations the book discusses before the matrix.",steps:[{title:"Key idea",body:"The matrix prioritises improvements on the three selection criteria of **time, cost and impact**."},{title:"Eliminate",body:"S-O-D belongs to FMEA; the others are not the book's criteria."}],final:"Impact, cost and time → answer **C**",whyWrong:["Incorrect — severity, occurrence and detection are the FMEA ratings that build an RPN.","Incorrect — these mix X-Y Matrix and Analyze/Measure ideas; they are not the selection criteria.","","Incorrect — scope, schedule and budget are general project-management constraints, not the book's three criteria."],bookRef:"Book pp. 557–559"},{id:"sv-5-1140",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"When is the Improvement Selection Matrix MOST useful?",options:["When only one or two simple controls are planned","When the root cause has not yet been verified","When a control chart has just signalled a special cause","When several improvement efforts are being considered"],answer:3,hint:"The tool earns its effort when there is something to rank.",steps:[{title:"Key idea",body:"The book: the tool is best used when **multiple improvement efforts** are considered; it is unnecessary for just a few changes."},{title:"Eliminate",body:"Verifying causes belongs to Analyze, and signals are handled by the OCAP."}],final:"Best with many candidate improvements → answer **D**",whyWrong:["Incorrect — the book says the tool is unnecessary for just a few changes to the process.","Incorrect — unverified root causes are an Analyze-phase task, not a reason to rank solutions.","Incorrect — a special-cause signal calls for the OCAP, not for selecting improvements.",""],bookRef:"Book pp. 557, 559"},{id:"sv-5-1141",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"In the Improvement Selection Matrix, what do the potential improvements listed down the side usually act on?",options:["The X's that drive the project outputs","The customer's specification limits","The project's financial targets","The significance ratings of the outputs"],answer:0,hint:"Y = f(X): improvements change inputs to move outputs.",steps:[{title:"Key idea",body:`The book: "The improvements, usually impacting the X's, are listed" and rated for their impact on each output.`},{title:"Eliminate",body:"Specs, money targets and significance ratings are not what an improvement changes."}],final:"Improvements act on the X's → answer **A**",whyWrong:["","Incorrect — specifications come from the customer; improvements change the process, not the specs.","Incorrect — financial benefit is verified later; improvements act on process inputs.","Incorrect — significance ratings are fixed from the X-Y Matrix; improvements are rated against them."],bookRef:"Book p. 559"},{id:"sv-5-1142",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"On the book's impact-rating scale, what does an impact rating of **7** mean?",options:["Personnel are trained about the X's impact on the output","The X is removed from impacting the process output","Process inspection or testing is improved to find defects","Defect detection stops unknown defects leaving the process"],answer:1,hint:"The top of the scale matches the most effective improvement type.",steps:[{title:"Key idea",body:"Impact 7 = X's are removed from impacting the process output — the root cause no longer acts."},{title:"Eliminate",body:"Detection (4), inspection (3) and training (1) sit lower on the scale."}],final:"Impact 7 = X removed → answer **B**",whyWrong:["Incorrect — training people about the X earns only an impact rating of 1.","","Incorrect — improved inspection or testing earns an impact rating of 3.","Incorrect — defect detection of the output earns an impact rating of 4."],bookRef:"Book p. 560"},{id:"sv-5-1143",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which impact rating does the book give when **defect detection of the process output** prevents unknown defects from leaving the process?",options:["2","3","4","5"],answer:2,hint:"Detection at the output sits just below control of the X's and just above better inspection.",steps:[{title:"Key idea",body:"Book scale: 5 = continual control of critical X's prevents defects; **4 = defect detection of the output stops unknown defects leaving**; 3 = improved inspection or testing."},{title:"Apply",body:"The stem describes output detection → 4."}],final:"Output defect detection = 4 → answer **C**",whyWrong:["Incorrect — 2 means the process is improved with easier control of a critical X.","Incorrect — 3 means process inspection or testing is improved to find defects better.","","Incorrect — 5 means continual control of critical X's prevents defects from that X."],bookRef:"Book p. 560"},{id:"sv-5-1144",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"On the cost-to-implement scale, which description earns a cost rating of **0**?",options:["Low costs that can be expensed with no capital authorisation","Medium capital priority because of the relative return on investment","Significant capital and ongoing expenses without alignment with business priorities","Minimal up-front and ongoing expenses"],answer:2,hint:"On the cost scale, 7 is cheapest and 0 is prohibitive.",steps:[{title:"Key idea",body:"Cost 0 = significant capital and ongoing expenses **without alignment with business priorities** — prohibitive."},{title:"Eliminate",body:"7 = minimal, 6/5 = expensed, 4 = medium capital priority."}],final:"Cost 0 = unaligned significant capital → answer **C**",whyWrong:["Incorrect — low, expensed costs earn a 5 or 6, among the most favourable ratings.","Incorrect — medium capital priority by relative ROI earns a 4.","","Incorrect — minimal costs earn the best rating of 7."],trap:"On the cost scale a high number is good news.",bookRef:"Book p. 560"},{id:"sv-5-1145",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Why does the book recommend a time rating of **0** for improvements that would take more than a year?",options:["Capital budgets are approved only once in each financial year","Control charts need a full year of data before limits are set","Improvements taking over a year cannot be rated for impact","Many businesses have product cycle times of less than a year"],answer:3,hint:"Think about how long a product or service stays relevant.",steps:[{title:"Key idea",body:'The book: many businesses have product cycle times under a year, so improvements that long are "ill considered".'},{title:"Eliminate",body:"Budget cycles, SPC data needs and impact rating are unrelated to the reason given."}],final:"Product cycles are shorter than a year → answer **D**",whyWrong:["Incorrect — budgeting cycles are not the book's reason for the zero rating.","Incorrect — control limits need about 20–25 subgroups, not a year of data.","Incorrect — such improvements can still be rated for impact; time is a separate criterion.",""],bookRef:"Book p. 561"},{id:"sv-5-1146",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"In the Improvement Selection Matrix, what does an output **significance rating of 1** mean?",options:["The output is not very important","The output is critical to the business","The improvement has no impact on the output","The improvement can be in place within a week"],answer:0,hint:"Significance runs 1–10 and describes outputs, not improvements.",steps:[{title:"Key idea",body:"Outputs (Y's) are rated 1–10 for importance: 1 = not very important, 10 = critical."},{title:"Eliminate",body:"Impact (0–7) and time (0–7) rate the improvements, not the outputs."}],final:"Significance 1 = not very important → answer **A**",whyWrong:["","Incorrect — a significance rating of 10 means the output is critical.","Incorrect — 'no impact' is an impact rating of 0, a different scale.","Incorrect — 'less than a week' is a time rating of 7, a different scale."],bookRef:"Book p. 560"},{id:"sv-5-1147",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which cost-to-implement rating describes costs that are **low and can be expensed with no capital authorisation**, but whose **recurring expenses are higher**?",options:["4","5","6","7"],answer:1,hint:"Two neighbouring ratings share 'expensed, no capital' — the recurring cost splits them.",steps:[{title:"Key idea",body:"Cost 6 = expensed, no capital, recurring expenses **low**; cost 5 = expensed, no capital, recurring expenses **higher**."},{title:"Apply",body:"Higher recurring expenses → 5."}],final:"Expensed with higher recurring cost = 5 → answer **B**",whyWrong:["Incorrect — 4 means a medium capital priority because of relative return on investment.","","Incorrect — 6 is the same expensed case but with low recurring expenses.","Incorrect — 7 means improvement costs are minimal, up front and ongoing."],bookRef:"Book p. 560"},{id:"sv-5-1148",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"Which question describes a **technical** time constraint for an improvement?",options:["What other priorities are competing for the technical people's time?","What is the minimum time it would take to build and implement it?","How long will it take to gain support from the necessary stakeholders?","How long will it take for the savings to repay the investment?"],answer:1,hint:"Technical = the build itself.",steps:[{title:"Key idea",body:"Technical constraint: the minimum time to build/create and implement the improvement."},{title:"Eliminate",body:"Political = competing priorities; cultural = stakeholder support; payback is not a time constraint."}],final:"Technical = minimum build-and-implement time → answer **B**",whyWrong:["Incorrect — competing priorities for technical time describe a political time constraint.","","Incorrect — winning stakeholder support describes a cultural time constraint.","Incorrect — repayment time is a financial measure, not one of the book's three time constraints."],bookRef:"Book p. 558"},{id:"sv-5-1149",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"Under the **impact** criterion, what does the book's 'time frame of improvements' consideration compare?",options:["Initial versus on-going cost","Technical versus cultural constraints","Long-term versus short-term effectiveness","Primary versus secondary metrics"],answer:2,hint:"Impact has two parts: time frame and type of improvement.",steps:[{title:"Key idea",body:"Impact considerations: the time frame (long-term vs short-term effectiveness) and the effectiveness of the improvement type."},{title:"Eliminate",body:"Costs and constraints are the other two criteria; metrics are the outputs."}],final:"Impact time frame = long vs short term → answer **C**",whyWrong:["Incorrect — initial versus on-going cost is part of the cost criterion.","Incorrect — technical and cultural constraints belong to the time criterion.","","Incorrect — primary and secondary metrics are the matrix outputs, not the impact time frame."],bookRef:"Book p. 557"},{id:"sv-5-1150",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"Selecting solutions in Control supports which overall objective stated by the book?",options:["To find new root causes not seen in Analyze","To estimate the cost of poor quality for the charter","To validate the measurement system for the Y","To sustain the gains found in the Define to Improve phases"],answer:3,hint:"What is the Control phase for?",steps:[{title:"Key idea",body:'The book: "The objective is to sustain the gains initially found in the D, M, A, I Phases."'},{title:"Eliminate",body:"Root causes, COPQ and MSA belong to earlier phases."}],final:"Sustain the gains → answer **D**",whyWrong:["Incorrect — finding root causes is the work of the Analyze phase.","Incorrect — COPQ is estimated in Define to justify the project.","Incorrect — measurement system validation is done in Measure.",""],bookRef:"Book p. 556"},{id:"sv-5-1151",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which is an obstacle the book says final decisions on defect-reduction tools may meet?",options:["Management buy-in is not yet complete","The Analyze-phase hypothesis tests must be repeated","The SIPOC diagram must be redrawn","The measurement system must be re-validated"],answer:0,hint:"The book lists three hurdles: money, people and support.",steps:[{title:"Key idea",body:"Final decisions may meet: capital expenditures, training hurdles and **management buy-in not completed**."},{title:"Eliminate",body:"The other options are earlier-phase tasks."}],final:"Buy-in not complete is a listed obstacle → answer **A**",whyWrong:["","Incorrect — hypothesis tests are finished in Analyze; they are not a listed obstacle to selection.","Incorrect — the SIPOC is a Define scoping tool, not a selection obstacle.","Incorrect — MSA is a Measure activity; the book lists capital, training and buy-in."],bookRef:"Book p. 556"},{id:"sv-5-1152",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"According to the book, who should make the ratings in the Improvement Selection Matrix?",options:["The Green Belt alone","The whole project team","The Finance department alone","The Champion alone"],answer:1,hint:"Ratings need the knowledge of everyone who understands the process.",steps:[{title:"Key idea",body:'The book: "your ratings of the solutions should involve your whole team".'},{title:"Eliminate",body:"Any single person or department rating alone misses the team's knowledge."}],final:"Whole team rates → answer **B**",whyWrong:["Incorrect — a single person's ratings lose the team's knowledge and understanding of priorities.","","Incorrect — Finance helps verify benefits but does not rate impact, cost and time alone.","Incorrect — the Champion supports the project but the ratings should involve the whole team."],bookRef:"Book p. 561"},{id:"sv-5-1153",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"What should implementation plans for the selected solutions emphasise, according to the book?",options:["Re-running the Analyze-phase hypothesis tests before each change","Re-scoping the project charter to match the chosen solutions","Organising tasks and resources, realistic deadlines and actions to ensure success","Recalculating the baseline sigma level before implementation"],answer:2,hint:"A plan is more than the back of an envelope.",steps:[{title:"Key idea",body:"Implementation plans should organise tasks and resources, establish realistic time frames and deadlines, and identify actions to ensure success."},{title:"Eliminate",body:"The other options repeat earlier-phase work."}],final:"Tasks, deadlines, actions → answer **C**",whyWrong:["Incorrect — hypothesis tests verified the X's earlier; implementation planning is about tasks and time.","Incorrect — the charter scope is fixed in Define; implementation plans organise delivery.","","Incorrect — the baseline was set in Measure; it is not an implementation-plan emphasis."],bookRef:"Book p. 562"},{id:"sv-5-1154",phase:5,topic:"5.3.1",qtype:"concept",difficulty:1,stem:"Once the solutions have been selected and planned, where does the book say all of them must be recorded?",options:["In the project charter","In the SIPOC diagram","In the cause-and-effect diagram","In the control plan document"],answer:3,hint:"The selected controls must live in the document that sustains them.",steps:[{title:"Key idea",body:'The book: "All solutions must be part of Control Plan Document."'},{title:"Eliminate",body:"Charter, SIPOC and fishbone are earlier-phase tools."}],final:"All solutions go in the control plan → answer **D**",whyWrong:["Incorrect — the charter defines the problem, goal and scope in Define; it is not updated with solutions.","Incorrect — the SIPOC scopes the process at a high level in Define.","Incorrect — the cause-and-effect diagram lists potential X's; it does not record chosen solutions.",""],bookRef:"Book p. 562"},{id:"sv-5-1155",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"What does the book say about the rating scales used in the Improvement Selection Matrix?",options:["They are guidelines that can be customised, but the chosen criteria should be standardised","They are fixed scales that must never be changed","They must match the FMEA severity scale exactly","They are set separately by Finance for each project"],answer:0,hint:"Like FMEA ratings: adapt them, then apply them consistently.",steps:[{title:"Key idea",body:"The book: these are general guideline ratings — customise them to meet your business, but try to standardise whatever criteria you choose."},{title:"Eliminate",body:"They are neither fixed, copied from FMEA, nor owned by Finance."}],final:"Customise, then standardise → answer **A**",whyWrong:["","Incorrect — the book calls them general guideline ratings to customise for your business.","Incorrect — the book compares them to FMEA ratings that may vary, not that they must copy FMEA.","Incorrect — the team rates improvements; Finance does not set the scales."],bookRef:"Book p. 560"},{id:"sv-5-1156",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which is listed in the book as a Control-phase **roadblock** linked to the business case?",options:["Control limits are recalculated after a verified shift","Financial benefits are not tracked and integrated into the business","Selection ratings are made by the whole team","Long improvements are run in parallel with quick ones"],answer:1,hint:"Roadblocks are things that stop gains from counting or lasting.",steps:[{title:"Key idea",body:"Control roadblocks include lack of sign-off, team not involved in the control plan, management lacking monitoring knowledge, **financial benefits not tracked**, and lack of operator buy-in."},{title:"Eliminate",body:"The other three are recommended practices."}],final:"Untracked benefits are a roadblock → answer **B**",whyWrong:["Incorrect — recalculating after a verified shift is good SPC practice, not a roadblock.","","Incorrect — team ratings are the book's recommended practice.","Incorrect — running improvements in parallel is recommended to avoid delays."],bookRef:"Book p. 577"},{id:"sv-5-1157",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Why are low-cost improvements that can simply be **expensed** often preferred?",options:["They always carry the highest impact rating in the matrix","They remove the root cause of the defect by definition","They are smaller and avoid capital authorisation, so they are faster to approve","They have no on-going costs to sustain the improvement"],answer:2,hint:"Capital approval takes time and competes for cash.",steps:[{title:"Key idea",body:"The book: expenditures that are not capitalised are usually desired because they are smaller and merely expensed."},{title:"Eliminate",body:"Funding route says nothing about impact, root cause or recurring cost."}],final:"Expensed = smaller, no capital approval → answer **C**",whyWrong:["Incorrect — cost and impact are separate criteria; a cheap fix can have low impact.","Incorrect — removing the root cause depends on the improvement type, not on how it is funded.","","Incorrect — expensed items can still have recurring costs (cost rating 5 vs 6)."],bookRef:"Book p. 560"},{id:"sv-5-1158",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the Improvement Selection Matrix is CORRECT?",options:["The overall rating is the sum of the impact, cost and time ratings","Significance ratings are set fresh, independently of the X-Y Matrix","Impact ratings run from 1 to 10 for each output","A cost or time rating of zero removes the improvement from consideration"],answer:3,hint:"Recall how a zero behaves in a product.",steps:[{title:"Key idea",body:"Overall rating = overall impact × cost × time, so a zero cost or time rating eliminates the option."},{title:"Eliminate",body:"Not a sum; significance comes from the X-Y Matrix; impact is 0–7."}],final:"Zero cost or time eliminates → answer **D**",whyWrong:["Incorrect — the overall impact is multiplied by the cost and time ratings, not added to them.","Incorrect — significance must match the updated X-Y Matrix rankings.","Incorrect — impact runs 0–7; 1–10 is the output significance scale.",""],bookRef:"Book pp. 559–561"},{id:"sv-5-1159",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the time-to-implement rating is CORRECT?",options:["A rating of 7 means the improvement can be in place and workable in less than a week","A rating of 0 means the improvement can be in place immediately","Time ratings exclude the time needed for the approvals process","Time ratings run from 1 to 10, like significance ratings"],answer:0,hint:"Higher time rating = faster.",steps:[{title:"Key idea",body:"Time scale: 7 = under a week … 0 = over a year; all times include approvals."},{title:"Eliminate",body:"0 is slowest, approvals are included, and the range is 0–7."}],final:"Time 7 = under a week → answer **A**",whyWrong:["","Incorrect — 0 means over a year, which removes the option from consideration.","Incorrect — the book states all times include time for the approvals process.","Incorrect — time is rated 0–7; 1–10 is the significance scale for outputs."],bookRef:"Book p. 561"},{id:"sv-5-1160",phase:5,topic:"5.3.1",qtype:"concept",difficulty:3,stem:"Which statement about the three time constraints is TRUE?",options:["A cultural constraint is the minimum time needed to build the improvement","A political constraint arises from other priorities competing for the technical time","A technical constraint is the time needed to gain stakeholder support","A political constraint applies only to improvements that need capital"],answer:1,hint:"Technical = build; political = competing priorities; cultural = support.",steps:[{title:"Key idea",body:"Political time constraint: what other priorities are competing for the technical time to build the improvement?"},{title:"Eliminate",body:"The technical and cultural definitions have been swapped in two options; capital is not part of the definition."}],final:"Political = competing priorities → answer **B**",whyWrong:["Incorrect — the minimum build time is the technical constraint.","","Incorrect — gaining stakeholder support is the cultural constraint.","Incorrect — competing priorities can delay any improvement, capital or not."],trap:"Political and cultural are the most often swapped pair.",bookRef:"Book p. 558"},{id:"sv-5-1161",phase:5,topic:"5.3.1",qtype:"concept",difficulty:3,stem:"When the project Y's are entered across the top of the selection matrix, which statement is CORRECT?",options:["Only the project's primary metric may be listed as an output","Outputs are listed down the side and improvements across the top","Another business output may be added to those carried over from the X-Y Matrix","Outputs are rated 0–7 for significance, like the improvements"],answer:2,hint:"The outputs usually resemble the X-Y Matrix — usually, not always.",steps:[{title:"Key idea",body:'The book: outputs "in most cases resemble those of your original X-Y Matrix but you might have another business output added".'},{title:"Eliminate",body:"Secondary metrics are included, the layout is Y's across the top, and significance is 1–10."}],final:"Extra business outputs allowed → answer **C**",whyWrong:["Incorrect — the book lists primary and secondary metrics as outputs.","Incorrect — the Y's go across the horizontal axis; improvements go down the side.","","Incorrect — outputs are rated 1–10 for significance; 0–7 is used for impact, cost and time."],bookRef:"Book pp. 559–560"},{id:"sv-5-1162",phase:5,topic:"5.3.1",qtype:"concept",difficulty:2,stem:"Which statement about selecting solutions is CORRECT?",options:["It is a statistical decision based only on the p-values from Analyze","It should follow the department that argues most strongly","It always needs the full selection matrix, even for two changes","It is a business decision that balances impact, cost and time against business needs"],answer:3,hint:"Statistical solution → practical solution.",steps:[{title:"Key idea",body:'"Selecting solutions comes down to a business decision" — impact, cost and timeliness balanced against business needs.'},{title:"Eliminate",body:"Not p-values alone, not the loudest department, and not always the full tool."}],final:"A business decision → answer **D**",whyWrong:["Incorrect — p-values proved the X's; choosing practical solutions is a business decision.","Incorrect — the book says to balance departmental wishes with a quantified evaluation.","Incorrect — the book says the tool is unnecessary for just a few changes.",""],bookRef:"Book p. 557"},{id:"sv-5-1163",phase:5,topic:"5.3.1",qtype:"concept",difficulty:3,stem:"Which statement about scheduling the selected improvements is CORRECT?",options:["Long capital investments should run in parallel with quicker improvements to avoid further delays","Only the single highest-rated improvement may be implemented","Improvements must be implemented strictly one after another in rating order","An improvement with a time rating of zero should be run in parallel"],answer:0,hint:"Priority order is not the same as a strict queue.",steps:[{title:"Key idea",body:"The book: long time-frame capital investments should have parallel efforts so delays do not keep occurring; do NOT forget running improvements in parallel."},{title:"Eliminate",body:"Zero-rated options are dropped, not run in parallel."}],final:"Run long items in parallel → answer **A**",whyWrong:["","Incorrect — the matrix ranks priorities; several improvements can be implemented.","Incorrect — the book warns not to forget running improvements in parallel.","Incorrect — a zero time rating removes the improvement from consideration altogether."],bookRef:"Book p. 561"},{id:"sv-5-1164",phase:5,topic:"5.3.1",qtype:"statements",difficulty:2,stem:`Consider these statements about the rating scales in the Improvement Selection Matrix:

1. Cost-to-implement ratings range from 1 to 10.
2. Impact ratings range from 0 to 7.
3. Output significance ratings range from 1 to 10.
4. A time rating of 7 means more than a year to implement.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Only the outputs use 1–10; everything rated for an improvement uses 0–7.",steps:[{title:"Key idea",body:"Significance of outputs: 1–10. Impact, cost and time of improvements: 0–7."},{title:"Apply",body:"Statements 2 and 3 are true; 1 (cost 1–10) and 4 (7 = over a year) are false."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: cost is rated 0 to 7, like impact and time.","","Incorrect — statement 4 is false: a time rating of 7 means less than a week.","Incorrect — both are false: cost runs 0–7 and a time rating of 7 is the fastest."],bookRef:"Book pp. 559–561"},{id:"sv-5-1165",phase:5,topic:"5.3.1",qtype:"statements",difficulty:3,stem:`Consider these statements about the **cost** criterion:

1. On-going costs include future inspection and monitoring.
2. Improvements needing capital earn a higher cost rating than expensed ones.
3. A cost rating of 0 is the most favourable score.
4. Training the existing workforce is an initial cost.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Split initial from on-going costs, and remember which end of the scale is good.",steps:[{title:"Key idea",body:"Initial: training the existing workforce, new materials, build resources, capital. On-going: future training, inspection, monitoring, materials. Cost 7 = minimal, 0 = prohibitive."},{title:"Apply",body:"Statements 1 and 4 are true."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: expensed improvements earn the higher (better) ratings of 5–6.","Incorrect — both are false: capital needs lower the rating, and 0 is prohibitive.","Incorrect — statement 3 is false: 0 is the prohibitive end of the scale; 7 is the best.",""],bookRef:"Book pp. 558, 560"},{id:"sv-5-1166",phase:5,topic:"5.3.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

[?] time constraints ask which other priorities are competing for the technical time needed to build the improvement.`,options:["Cultural","Financial","Political","Technical"],answer:2,hint:"Competing priorities = organisational politics.",steps:[{title:"Key idea",body:"Technical = minimum build time; political = competing priorities; cultural = stakeholder support."},{title:"Apply",body:"Competing priorities → political."}],final:"Political → answer **C**",whyWrong:["Incorrect — cultural constraints ask how long it will take to gain stakeholder support.","Incorrect — financial is not one of the book's three time constraints.","","Incorrect — technical constraints ask for the minimum time to build and implement."],bookRef:"Book p. 558"},{id:"sv-5-1167",phase:5,topic:"5.3.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In the Improvement Selection Matrix, the overall rating is the overall impact rating [?] by the cost rating and the time rating.`,options:["added","averaged","divided","multiplied"],answer:3,hint:"This is why a zero on cost or time knocks an option out.",steps:[{title:"Key idea",body:'The book: "The cost and timing ratings are multiplied against the overall impact rating."'},{title:"Apply",body:"Multiplication explains why any zero gives an overall rating of zero."}],final:"multiplied → answer **D**",whyWrong:["Incorrect — adding would let a zero cost or time rating leave the option in contention.","Incorrect — averaging is not the book's method and would dilute a prohibitive zero.","Incorrect — dividing would reward high cost, the opposite of the scale's meaning.",""],bookRef:"Book p. 559"},{id:"sv-5-1168",phase:5,topic:"5.3.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A cost benefit analysis is always a good tool to use to assist in determining the [?].`,options:["baseline","priorities","root causes","specifications"],answer:1,hint:"Cost-benefit analysis helps decide what to do first.",steps:[{title:"Key idea",body:"The book: selecting solutions is a business decision, and a cost benefit analysis helps determine the **priorities**."},{title:"Eliminate",body:"Baseline, root causes and specifications are set earlier or by the customer."}],final:"priorities → answer **B**",whyWrong:["Incorrect — the baseline is established in Measure, not by cost-benefit analysis.","","Incorrect — root causes are proven in Analyze before solutions are selected.","Incorrect — specifications come from the voice of the customer."],bookRef:"Book p. 557"},{id:"sv-5-1169",phase:5,topic:"5.3.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

When balancing wishes, the book notes that engineering always wants the [?], sales always wants inventory and production always wants more capacity.`,options:["cheapest option","fastest fix","gold standard","shortest lead time"],answer:2,hint:"Each function pulls toward its own ideal; the matrix balances them.",steps:[{title:"Key idea",body:"The book: balance desire with quantifiable evaluation — engineering wants the **gold standard**, sales wants inventory, production wants capacity."},{title:"Apply",body:"The selection matrix turns these competing wishes into an objective ranking."}],final:"gold standard → answer **C**",whyWrong:["Incorrect — cost pressure is not the wish the book attributes to engineering.","Incorrect — quick fixes are not engineering's stated wish in the book.","","Incorrect — lead time is not what the book says engineering always wants."],bookRef:"Book p. 557"},{id:"sv-5-1170",phase:5,topic:"5.3.1",qtype:"not-except",difficulty:1,stem:"Which is NOT an initial (one-time) cost of implementing an improvement?",options:["Training the existing workforce","Future inspection and monitoring","Purchasing new materials for the improvement","Any capital investment required"],answer:1,hint:"Ask: does the cost happen once, or keep recurring to sustain the change?",steps:[{title:"Key idea",body:"Initial: train existing staff, new materials, build resources, capital. On-going: future training, inspection, monitoring and materials."},{title:"Apply",body:"Future inspection and monitoring recur → not initial."}],final:"Monitoring is on-going → answer **B**",whyWrong:["Incorrect — training the current workforce is listed as an initial cost.","","Incorrect — buying new materials needed for the improvement is an initial cost.","Incorrect — capital investment is an initial cost."],bookRef:"Book p. 558"},{id:"sv-5-1171",phase:5,topic:"5.3.1",qtype:"not-except",difficulty:2,stem:"Which is NOT one of the improvement types the book ranks when judging the effectiveness of an improvement?",options:["Removing the root cause of the defect","Monitoring or flagging the condition that produces a defect","Redefining the project scope","Training people not to produce defects"],answer:2,hint:"The four types: remove, flag, inspect, train.",steps:[{title:"Key idea",body:"Effectiveness types: remove the root cause > monitor/flag the condition > inspect for the defect > train people."},{title:"Apply",body:"Changing the project scope is a Define activity, not an improvement type."}],final:"Scope change is not an improvement type → answer **C**",whyWrong:["Incorrect — removing the root cause is the most effective type listed.","Incorrect — monitoring or flagging the condition is the second type listed.","","Incorrect — training people is listed, as the least effective type."],bookRef:"Book p. 557"},{id:"sv-5-1172",phase:5,topic:"5.3.1",qtype:"not-except",difficulty:1,stem:"Which is NOT one of the three time constraints the book lists for implementing an improvement?",options:["Cultural","Financial","Political","Technical"],answer:1,hint:"Technical, political, cultural.",steps:[{title:"Key idea",body:"The book lists technical, political and cultural time constraints."},{title:"Apply",body:"Money belongs to the cost criterion, so 'financial' is the outsider."}],final:"Financial is not a time constraint → answer **B**",whyWrong:["Incorrect — cultural (gaining stakeholder support) is one of the three.","","Incorrect — political (competing priorities) is one of the three.","Incorrect — technical (minimum build and implement time) is one of the three."],bookRef:"Book p. 558"},{id:"sv-5-1173",phase:5,topic:"5.3.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a component of an implementation plan for the selected solutions, according to the book?",options:["A work breakdown structure","A risk management plan","An influence strategy for priorities and resourcing","A process capability study"],answer:3,hint:"Implementation planning is project management: WBS, influence, risk, audit.",steps:[{title:"Key idea",body:"Components: work breakdown structure, influence strategy, risk management plan, audit results for completion and risks."},{title:"Apply",body:"A capability study measures performance; it is not an implementation-plan component."}],final:"Capability study is the outsider → answer **D**",whyWrong:["Incorrect — a work breakdown structure is a listed component.","Incorrect — a risk management plan is a listed component.","Incorrect — an influence strategy for priorities and resourcing is a listed component.",""],bookRef:"Book p. 562"},{id:"sv-5-1174",phase:5,topic:"5.3.1",qtype:"scenario",difficulty:2,stem:"A Green Belt finds that the developers needed to build an automatic order-validation rule are booked on a regulatory billing release for the next two months. Which time constraint does this describe?",options:["Cultural time constraint","Initial cost constraint","Political time constraint","Technical time constraint"],answer:2,hint:"Who else wants the same people's time?",steps:[{title:"Key idea",body:"Political constraint = other priorities competing for the technical time to build the improvement."},{title:"Apply",body:"The developers are tied up on another priority → political."}],final:"Competing release = political → answer **C**",whyWrong:["Incorrect — a cultural constraint is about winning stakeholder support for the change.","Incorrect — this is about people's time, not money; initial cost is part of the cost criterion.","","Incorrect — a technical constraint is the minimum time to build the rule, not competing work."],bookRef:"Book p. 558"},{id:"sv-5-1175",phase:5,topic:"5.3.1",qtype:"scenario",difficulty:3,stem:"A cable supplier will lose its largest customer next month unless defective batches stop reaching that customer. The permanent design fix needs eight months. Which approach does the book's impact guidance support?",options:["Put a short-term containment in place first while the long-term fix proceeds","Wait for the redesign, because long-term effectiveness always comes first","Train operators instead, because training is the most effective improvement","Reject the redesign, because anything over six months is eliminated"],answer:0,hint:"Time frame of improvements: long-term versus short-term.",steps:[{title:"Key idea",body:'The book: "If a supplier will lose a major customer because of defects the short term benefit will prevail first."'},{title:"Apply",body:"Contain now, and keep the permanent fix running in parallel."}],final:"Short term first when a major customer is at risk → answer **A**",whyWrong:["","Incorrect — the book says that when a major customer is at risk, the short-term benefit prevails first.","Incorrect — training is ranked the least effective improvement type.","Incorrect — only over a year earns a time rating of 0; eight months is still rateable."],bookRef:"Book pp. 557, 561"},{id:"sv-5-1176",phase:5,topic:"5.3.1",qtype:"scenario",difficulty:2,stem:"To stop wrong tariff codes, a team adds a system rule that makes it impossible to save an order without a valid code. Which improvement type from the book's effectiveness list is this?",options:["Monitoring or flagging the condition that produces a defect","Removing the root cause of the defect","Inspecting to determine whether the defect occurred","Training people not to produce defects"],answer:1,hint:"Can the defect still happen?",steps:[{title:"Key idea",body:"The most effective type removes the root cause so the defect cannot occur."},{title:"Apply",body:"An invalid code can no longer be saved → the cause is removed (impact rating 7 territory)."}],final:"Error made impossible = root cause removed → answer **B**",whyWrong:["Incorrect — flagging detects the condition after it appears; here the wrong code cannot be entered at all.","","Incorrect — inspection checks for defects afterwards; this rule prevents them.","Incorrect — no training is involved; the system itself blocks the error."],bookRef:"Book pp. 557, 560"},{id:"sv-5-1177",phase:5,topic:"5.3.1",qtype:"scenario",difficulty:2,stem:"For a modem-repair process, engineering proposes a fully automated test line, sales asks for extra buffer stock, and production wants a second shift. What does the book recommend the Green Belt do?",options:["Choose engineering's proposal because it gives the highest quality","Let the Champion pick the department with the largest budget","Balance these wishes with a quantified evaluation of impact, cost and time","Implement all three proposals to keep every department satisfied"],answer:2,hint:"Desire versus quantifiable evaluation.",steps:[{title:"Key idea",body:"The book: balance desire with quantifiable evaluation — engineering, sales and production each pull their own way."},{title:"Apply",body:"Rate each option on impact, cost and time and rank them objectively."}],final:"Quantify, then balance → answer **C**",whyWrong:["Incorrect — the gold standard is engineering's wish, not an objective choice.","Incorrect — budget size is not one of the selection criteria.","","Incorrect — doing everything ignores cost and time and is not prioritisation."],bookRef:"Book p. 557"},{id:"sv-5-1178",phase:5,topic:"5.3.1",qtype:"scenario",difficulty:3,stem:"A team adds a step that improves the final test so faulty set-top boxes are found more reliably before shipment. The root cause is unchanged. Which impact rating does this match on the book's scale?",options:["1","3","5","7"],answer:1,hint:"Better inspection finds defects; it does not stop them.",steps:[{title:"Key idea",body:"Impact 3 = process inspection or testing is improved to find defects better."},{title:"Apply",body:"The change improves testing only → 3."}],final:"Improved testing = 3 → answer **B**",whyWrong:["Incorrect — 1 is for training personnel about the X's impact.","","Incorrect — 5 needs continual control of the critical X's that prevents the defect.","Incorrect — 7 needs the X removed from impacting the output; the cause is unchanged."],bookRef:"Book p. 560"},{id:"sv-5-1179",phase:5,topic:"5.3.1",qtype:"scenario",difficulty:3,stem:"Improvement A has an impact rating of 4 on each of three outputs. Improvement B has an impact rating of 4 on only one of those outputs, and 0 on the others. What does the book say about their overall impact ratings?",options:["B will have the higher overall impact because it focuses on one output","Both will be equal because the overall impact ignores how many outputs are hit","They cannot be compared until the cost ratings are known","A will have the higher overall impact because impacts on several outputs add up"],answer:3,hint:"Overall impact is summed across every output.",steps:[{title:"Key idea",body:"The book: items having more impacts on multiple outputs will have a higher overall impact rating."},{title:"Apply",body:"A contributes on three outputs, B on one → A is higher."}],final:"More outputs hit → higher overall impact → answer **D**",whyWrong:["Incorrect — focus earns no bonus; zeros on the other outputs add nothing.","Incorrect — overall impact is a sum across all outputs, so more impacted outputs raise it.","Incorrect — overall impact is computed before cost and time are applied.",""],bookRef:"Book p. 559"},{id:"sv-5-1180",phase:5,topic:"5.3.1",qtype:"best-action",difficulty:2,stem:"To save time, a Green Belt completes the Improvement Selection Matrix alone overnight and presents the ranking as final. Was this appropriate?",options:["Yes, because the Belt is accountable for the selection decision","Yes, because standard rating scales make team input unnecessary","No, because only Finance may rate the cost and time criteria","No, because the ratings should draw on the whole team's knowledge"],answer:3,hint:"Who does the book say should rate the solutions?",steps:[{title:"Key idea",body:"The book: ratings of the solutions should involve the whole team to capture their knowledge and understanding of final priorities."},{title:"Apply",body:"A ranking built alone lacks that input → not appropriate."}],final:"Rate with the whole team → answer **D**",whyWrong:["Incorrect — accountability does not replace the team's knowledge in the ratings.","Incorrect — the scales are guidelines; judgement is still needed from those who know the process.","Incorrect — the book does not reserve cost or time ratings for Finance.",""],bookRef:"Book p. 561"},{id:"sv-5-1181",phase:5,topic:"5.3.1",qtype:"best-action",difficulty:1,stem:"The improved process is stable and the control plan has been handed to the process owner. What should the Green Belt do BEFORE moving to the next project?",options:["Verify the financial impact of the project","Rebuild the X-Y Matrix with new ratings","Repeat the Measure-phase capability baseline","Start a new Improvement Selection Matrix"],answer:0,hint:"Look at the last box of the Control roadmap.",steps:[{title:"Key idea",body:"The Control roadmap ends: align systems and structures → **verify financial impact** → go to next project."},{title:"Eliminate",body:"The other options repeat earlier work."}],final:"Verify financial impact last → answer **A**",whyWrong:["","Incorrect — the X-Y Matrix was used to prioritise inputs earlier; it is not the closing step.","Incorrect — the baseline was set in Measure; final capability is already part of Control.","Incorrect — selection happened before implementation; it is not the final step."],bookRef:"Book p. 578"},{id:"sv-5-1182",phase:5,topic:"5.3.1",qtype:"best-action",difficulty:3,stem:'Two improvements have equal cost and time ratings. Option P removes the root cause of mis-billing; option Q trains agents to spot it. The team picks Q because "people are our greatest asset". Was this appropriate?',options:["Yes, because training is ranked the most effective improvement type","Yes, because training costs are only ever initial costs","No, because removing the root cause is ranked more effective than training","No, because training cannot be listed in the selection matrix"],answer:2,hint:"Cost and time are tied, so impact decides.",steps:[{title:"Key idea",body:"Effectiveness: remove root cause > monitor/flag > inspect > train."},{title:"Apply",body:"With cost and time equal, P's higher impact should win → not appropriate."}],final:"Root-cause removal beats training → answer **C**",whyWrong:["Incorrect — training is the least effective type in the book's ranking.","Incorrect — future training is an on-going cost; cost is tied anyway.","","Incorrect — training can be listed; it simply earns an impact rating of 1."],bookRef:"Book pp. 557, 560"},{id:"sv-5-1183",phase:5,topic:"5.3.1",qtype:"best-action",difficulty:3,stem:"During implementation, the cost estimate of the second-ranked improvement grows from an expensed item to significant capital that is not in the business plan. What is the BEST action?",options:["Keep the original ranking because ratings are fixed once made","Re-rate its cost with the team and re-rank the improvements","Drop the cost criterion and rank on impact alone","Ask Finance to raise the improvement's impact rating"],answer:1,hint:"New cost information changes the cost rating — possibly to 0.",steps:[{title:"Key idea",body:"Cost 0 = significant capital without alignment with business priorities, which eliminates an option."},{title:"Apply",body:"Re-rate with the team and let the overall ratings re-rank the options."}],final:"Re-rate and re-rank → answer **B**",whyWrong:["Incorrect — ratings reflect current knowledge; a major cost change must be re-rated.","","Incorrect — cost is one of the three selection criteria and cannot be ignored.","Incorrect — impact is judged on effect on the outputs, not adjusted to offset cost."],bookRef:"Book pp. 560–561"},{id:"sv-5-1184",phase:5,topic:"5.3.1",qtype:"output",difficulty:3,stem:`A provisioning team completes its Improvement Selection Matrix:

\`\`\`
Improvement               Overall   Cost    Time    Overall
                          impact    rating  rating  rating
Auto-validate address       120       6       5      3600
Retrain order desk           40       7       7      1960
New CRM platform            180       0       2         0
Weekly order audit           70       5       6      2100
\`\`\`

Which improvement should be given first priority?`,options:["Auto-validate address","Retrain order desk","New CRM platform","Weekly order audit"],answer:0,hint:"Rank on the overall rating, not on any single column.",steps:[{title:"Key idea",body:"Improvements with the highest overall rating get first priority; a 0 cost or time rating eliminates an option."},{title:"Apply",body:"Auto-validate address has the highest overall rating (3600)."}],final:"Highest overall rating = 3600 → answer **A**",whyWrong:["","Incorrect — it has the best cost and time ratings but a low overall rating.","Incorrect — highest impact, but a cost rating of 0 makes its overall rating 0 and removes it.","Incorrect — second-highest overall rating, not the highest."],bookRef:"Book p. 561"},{id:"sv-5-1185",phase:5,topic:"5.3.1",qtype:"output",difficulty:2,stem:`An Improvement Selection Matrix summary is shown:

\`\`\`
Improvement                 Overall   Cost    Time    Overall
                            impact    rating  rating  rating
Auto-close duplicate tickets   96       6       6      3456
Replace legacy probes         150       3       2       900
Agent refresher session        30       7       7      1470
\`\`\`

What does the time rating of 2 for **Replace legacy probes** indicate?`,options:["About 7–14 days to be in place and workable","Over a year, so the option is eliminated","About 6–9 months to be in place and workable, including approvals","Two weeks of technical build time, excluding approvals"],answer:2,hint:"Time scale: 7 = under a week … 0 = over a year.",steps:[{title:"Key idea",body:"Time 2 = 6–9 months to get the improvement in place and workable; all times include approvals."},{title:"Eliminate",body:"6 = 7–14 days; 0 = over a year."}],final:"Time 2 = 6–9 months → answer **C**",whyWrong:["Incorrect — 7–14 days earns a time rating of 6.","Incorrect — over a year earns a 0; a 2 is still in consideration.","","Incorrect — the scale is not in weeks, and all times include approvals."],bookRef:"Book p. 561"},{id:"sv-5-1186",phase:5,topic:"5.3.1",qtype:"output",difficulty:2,stem:`Part of an Improvement Selection Matrix for a billing project is shown:

\`\`\`
Output (significance)   Billing accuracy (10)  Wait time (6)  Repeat calls (8)
Agent script refresher          1                   1               1
Rating-engine fix               7                   0               5
\`\`\`

What do the impact ratings of 1 for **Agent script refresher** indicate?`,options:["The X is removed from impacting each output","The improvement has no impact on any output","Inspection is improved to find defects on each output","Personnel are only trained about the X's impact on each output"],answer:3,hint:"Read the impact scale from the bottom.",steps:[{title:"Key idea",body:"Impact 1 = personnel are trained about X's impact on the process output — the weakest non-zero impact."},{title:"Eliminate",body:"0 = no impact; 3 = better inspection; 7 = X removed."}],final:"Impact 1 = training only → answer **D**",whyWrong:["Incorrect — removing the X earns a 7, as the rating-engine fix does for billing accuracy.","Incorrect — no impact is a 0.","Incorrect — improved inspection earns a 3.",""],bookRef:"Book p. 560"},{id:"sv-5-1187",phase:5,topic:"5.3.1",qtype:"output",difficulty:3,stem:`Output significances are 9, 6 and 4. Two improvements were rated:

\`\`\`
Improvement            Impact ratings   Overall   Cost    Time    Overall
                       (3 outputs)      impact    rating  rating  rating
New wall posters        0   0   0          0        7       7         0
SMS reminder            4   2   0         48        6       6      1728
\`\`\`

Which statement about **New wall posters** is correct?`,options:["It ranks last because it has no impact on any output, despite top cost and time ratings","It ranks first because its cost and time ratings are the highest","It is eliminated because its cost rating is zero","It must be re-rated because an overall impact can never be zero"],answer:0,hint:"Cheap and fast cannot rescue an option that changes nothing.",steps:[{title:"Key idea",body:"Overall rating = overall impact × cost × time; impact 0 = no impact on the output."},{title:"Apply",body:"The printed overall rating is 0, so it ranks last even with 7s for cost and time."}],final:"Zero impact → zero overall → answer **A**",whyWrong:["","Incorrect — cost and time multiply the impact; with zero impact the overall rating is zero.","Incorrect — its cost rating is 7 (minimal cost); the zero is in impact.","Incorrect — an impact of 0 is a valid rating meaning the X's have no impact."],bookRef:"Book pp. 559–560"},{id:"sv-5-1188",phase:5,topic:"5.3.1",qtype:"output",difficulty:2,stem:`The closure checklist for a fibre-installation project reads:

\`\`\`
Control phase checklist - Project FTTH-07
Is there a control plan in place?                  Yes
Has it been handed off to the process owner?       Yes
Is there an updated FMEA?                          Yes
Does the Champion agree the project is complete?   Yes
Does the Belt agree the project is complete?       Yes
Does Finance agree the project is complete?        Pending
\`\`\`

Based on the book's checklist, which conclusion is correct?`,options:["The project can close because the Champion has agreed","The project is not ready to close until Finance agrees it is complete","The project can close because the control plan has been handed off","Finance agreement is needed only for projects that used capital"],answer:1,hint:"Three parties must agree, not two.",steps:[{title:"Key idea",body:'Book checklist: "Do the Champion, the Belt and Finance all agree this project is complete?" — linked to verifying financial impact.'},{title:"Apply",body:"Finance is pending → not ready to close."}],final:"Finance pending → not closed → answer **B**",whyWrong:["Incorrect — the book asks whether the Champion, the Belt and Finance all agree.","","Incorrect — handoff is necessary but does not replace verifying the financial impact.","Incorrect — the checklist question applies to every project, not only capital ones."],bookRef:"Book p. 578"},{id:"sv-5-1189",phase:5,topic:"5.3.1",qtype:"output",difficulty:2,stem:`A team classified the costs of a new SIM-activation check:

\`\`\`
Row  Cost item                          Classified as
1    Capital for a new test server      Initial
2    Training current retail agents     Initial
3    Monthly SPC monitoring             On-going
4    Training future new hires          Initial
\`\`\`

Which row is classified INCORRECTLY?`,options:["Row 1","Row 2","Row 3","Row 4"],answer:3,hint:"Existing staff = initial; future training = on-going.",steps:[{title:"Key idea",body:"Initial: train existing workforce, materials, build resources, capital. On-going: future training, inspection, monitoring, materials."},{title:"Apply",body:"Training future new hires is on-going, so Row 4 is wrong."}],final:"Future training is on-going → answer **D**",whyWrong:["Incorrect — capital investment is an initial cost.","Incorrect — training the existing workforce is an initial cost.","Incorrect — monitoring is an on-going cost to sustain the improvement.",""],bookRef:"Book p. 558"},{id:"sv-5-1190",phase:5,topic:"5.3.1",qtype:"output",difficulty:3,stem:`A team logged the delays to its new auto-routing rule:

\`\`\`
Row  Delay                                              Constraint
1    Build and test take three weeks                    Technical
2    Developers pulled onto a billing-system release    Cultural
3    Supervisors need briefings before they back it     Cultural
4    Vendor needs ten days to configure the router      Technical
\`\`\`

Which row is labelled INCORRECTLY?`,options:["Row 1","Row 2","Row 3","Row 4"],answer:1,hint:"Competing priorities, not stakeholder support, explain Row 2.",steps:[{title:"Key idea",body:"Technical = build/implement time; political = competing priorities for the technical time; cultural = stakeholder support."},{title:"Apply",body:"Row 2 is a competing priority → political, not cultural."}],final:"Row 2 should be political → answer **B**",whyWrong:["Incorrect — build and test time is the technical constraint.","","Incorrect — winning supervisor support is a cultural constraint.","Incorrect — configuration time is part of the minimum build-and-implement (technical) time."],bookRef:"Book p. 558"},{id:"sv-5-1191",phase:5,topic:"5.3.1",qtype:"output",difficulty:2,stem:`The outputs entered in a contact-centre Improvement Selection Matrix are:

\`\`\`
Project output        Significance
Billing accuracy           10
Call wait time              5
Repeat contacts             8
\`\`\`

Which conclusion about these ratings is correct?`,options:["Call wait time is judged the most critical output","The numbers show the impact of each improvement on the outputs","Billing accuracy is judged twice as important as call wait time","The numbers must be re-scored 0–7 before they can be used"],answer:2,hint:"Significance ratings are relative rankings of the outputs.",steps:[{title:"Key idea",body:"The book: if one output is rated 10 and is twice the importance of a second, the second is rated 5."},{title:"Apply",body:"Billing accuracy 10 vs wait time 5 → twice as important."}],final:"10 vs 5 = twice as important → answer **C**",whyWrong:["Incorrect — 10 is the critical end of the scale; wait time has the lowest rating.","Incorrect — significance rates outputs; impact ratings are entered per improvement.","","Incorrect — significance is rated 1–10; 0–7 is for impact, cost and time."],bookRef:"Book p. 559"},{id:"sv-5-1192",phase:5,topic:"5.3.1",qtype:"true-false",difficulty:1,stem:"According to the book, the Improvement Selection Matrix is unnecessary when only a few changes are being made to the process. True or False?",options:["True","False"],answer:0,hint:"Smaller projects have few but vital control methods.",steps:[{title:"Key idea",body:"The book: the tool for selecting defect-prevention methods is unnecessary for just a few changes; smaller projects have few but vital controls."},{title:"Apply",body:"The statement matches the book → True."}],final:"Few changes → no matrix needed → answer **A**",whyWrong:["","Incorrect — the book states the selection tool is unnecessary for just a few changes."],bookRef:"Book p. 557"},{id:"sv-5-1193",phase:5,topic:"5.3.1",qtype:"sequence",difficulty:1,stem:`Put the book's progression of a Six Sigma project in order:

- **P** — Practical solution
- **Q** — Statistical problem
- **R** — Practical problem
- **S** — Statistical solution`,options:["Q, R, S, P","R, S, Q, P","R, Q, P, S","R, Q, S, P"],answer:3,hint:"Practical → statistical → statistical → practical.",steps:[{title:"Key idea",body:"Practical problem → statistical problem → statistical solution → practical solution."},{title:"Apply",body:"Cost-benefit analysis judges the practical solution from a business decision point of view."}],final:"R, Q, S, P → answer **D**",whyWrong:["Incorrect — a practical problem must be stated before it is turned into a statistical one.","Incorrect — the statistical problem must be defined before a statistical solution is found.","Incorrect — the practical solution comes last, after the statistical solution.",""],bookRef:"Book p. 557"},{id:"sv-5-1194",phase:5,topic:"5.3.1",qtype:"sequence",difficulty:2,stem:`Put the steps for building an Improvement Selection Matrix in order:

- **P** — Rate the cost and time of each improvement and find the overall rating
- **Q** — List the potential improvements down the side
- **R** — List the project outputs across the top with their significance ratings
- **S** — Rate each improvement's impact on each output`,options:["R, Q, S, P","Q, R, S, P","R, S, Q, P","R, Q, P, S"],answer:0,hint:"Outputs → improvements → impact → cost and time.",steps:[{title:"Key idea",body:"Y's across the top with 1–10 significance → improvements down the side → impact 0–7 → cost and time 0–7 → overall rating."},{title:"Apply",body:"R, Q, S, P."}],final:"R, Q, S, P → answer **A**",whyWrong:["","Incorrect — the outputs and their significance are set first, carried over from the X-Y Matrix.","Incorrect — impacts cannot be rated before the improvements are listed.","Incorrect — cost and time multiply the overall impact, so impact must be rated first."],bookRef:"Book pp. 559–561"},{id:"sv-5-1195",phase:5,topic:"5.3.1",qtype:"sequence",difficulty:2,stem:`Rank these improvement types from **MOST** to **LEAST** effective, as listed by the book:

- **P** — Inspecting to determine if the defect occurred
- **Q** — Training people not to produce defects
- **R** — Removing the root cause of the defect
- **S** — Monitoring or flagging the condition that produces a defect`,options:["R, P, S, Q","R, S, P, Q","S, R, P, Q","R, S, Q, P"],answer:1,hint:"Prevent > flag > inspect > train.",steps:[{title:"Key idea",body:"Book order: remove root cause > monitor/flag the condition > inspect for the defect > train people."},{title:"Apply",body:"R, S, P, Q."}],final:"R, S, P, Q → answer **B**",whyWrong:["Incorrect — flagging the condition comes before inspecting for the defect.","","Incorrect — removing the root cause outranks flagging the condition.","Incorrect — training is the least effective type, below inspection."],bookRef:"Book p. 557"},{id:"sv-5-1196",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"How does the book define a **control plan**?",options:["A detailed operating instruction for every step of the process","A list of the hypothesis tests planned for the Analyze phase","A written summary of the systems used to monitor and control process or product variation","A schedule of project milestones and tollgate review dates"],answer:2,hint:"Think 'summary of monitoring and control methods'.",steps:[{title:"Key idea",body:"Control plan = written summary describing systems used for monitoring and controlling process or product variation."},{title:"Eliminate",body:"It does not replace work instructions, test plans or the project schedule."}],final:"Written summary of control systems → answer **C**",whyWrong:["Incorrect — the book says the control plan is NOT a replacement for detailed operating instructions.","Incorrect — hypothesis tests belong to Analyze, not to the control plan.","","Incorrect — milestones belong to the project plan, not the control plan."],bookRef:"Book p. 562"},{id:"sv-5-1197",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which control-plan element includes updated process maps, SOPs and the FMEA?",options:["Documentation plan","Monitoring plan","Response plan","Training plan"],answer:0,hint:"Which plan keeps the written record current?",steps:[{title:"Key idea",body:"Documentation plan: process documentation (process maps, SOPs, FMEA) plus control-plan documentation."},{title:"Eliminate",body:"Monitoring, response and training plans cover other content."}],final:"Documentation plan → answer **A**",whyWrong:["","Incorrect — the monitoring plan defines what is sampled and measured and how charts are used.","Incorrect — the response plan says what to do when monitoring shows a defect or out-of-control signal.","Incorrect — the training plan covers who is trained, by whom and when."],bookRef:"Book p. 567"},{id:"sv-5-1198",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which control-plan element sets out **when to sample, how to sample and how to measure**?",options:["Documentation plan","Monitoring plan","Response plan","Training plan"],answer:1,hint:"Which plan watches the process after handoff?",steps:[{title:"Key idea",body:"The monitoring plan covers knowledge tests (when, how to sample, how to measure), SPC charts, FMEA, checklists and visual management."},{title:"Eliminate",body:"The other elements document, react and train."}],final:"Monitoring plan → answer **B**",whyWrong:["Incorrect — the documentation plan lists which documents are kept current and who updates them.","","Incorrect — the response plan acts after monitoring finds a problem.","Incorrect — the training plan covers who needs training and when."],bookRef:"Book p. 569"},{id:"sv-5-1199",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"In the book's diagram of control-plan elements, where does the control plan sit?",options:["Between the project charter and the baseline measurement","Between root-cause verification and solution generation","Between the SIPOC and the detailed process map","Between the implemented improvements and the verified financial impact"],answer:3,hint:"The control plan comes after the change and before the money is confirmed.",steps:[{title:"Key idea",body:"The diagram runs from implemented improvements → control plan (five elements; process owners accountable) → verified financial impact."},{title:"Eliminate",body:"All other pairs are earlier-phase steps."}],final:"After implementation, before verified impact → answer **D**",whyWrong:["Incorrect — the charter and baseline belong to Define and Measure.","Incorrect — root-cause verification and solution generation belong to Analyze and Improve.","Incorrect — SIPOC and process maps are Define and Measure tools.",""],bookRef:"Book p. 564"},{id:"sv-5-1200",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which control-plan element does the book describe as the basis for allowing people to change their behaviours **permanently**?",options:["Aligning systems and structures","Documentation plan","Monitoring plan","Training plan"],answer:0,hint:"Goals, policies, job descriptions and incentives.",steps:[{title:"Key idea",body:'Book: "Systems and structures are the basis for allowing people to change their behaviors permanently."'},{title:"Eliminate",body:"The other elements support the change but do not align incentives."}],final:"Aligning systems and structures → answer **A**",whyWrong:["","Incorrect — documentation shares and institutionalises what was learned, but does not change incentives.","Incorrect — monitoring checks that gains are sustained; it does not reshape behaviour.","Incorrect — training builds knowledge, but goals and incentives make behaviour permanent."],bookRef:"Book p. 572"},{id:"sv-5-1201",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Why is the control plan filed as part of the organisation's project-tracking mechanism?",options:["To track benefits and serve as a reference if results are not sustained","To replace the final project report","To record the hypothesis tests used in Analyze","To schedule the Green Belt's next project"],answer:0,hint:"Two reasons: benefits and a fall-back reference.",steps:[{title:"Key idea",body:"The control plan is filed as part of the tracking mechanism to **track benefits** and as a **reference for unsustained results**."},{title:"Eliminate",body:"It is part of, not a replacement for, the final report."}],final:"Track benefits; reference if gains slip → answer **A**",whyWrong:["","Incorrect — the book calls the control plan an essential portion of the final report, not a replacement.","Incorrect — test records sit in the project file; this is not why the plan is filed.","Incorrect — filing the plan is about the current process, not the Belt's next assignment."],bookRef:"Book p. 562"},{id:"sv-5-1202",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"According to the book, who is responsible for **developing** the monitoring plan?",options:["The functional managers","The Belt, helped by team members","The process owner alone","The training department"],answer:1,hint:"Develop versus adhere are different roles.",steps:[{title:"Key idea",body:"Book: the Belt is responsible for developing the monitoring plan; team members help; stakeholders are consulted."},{title:"Eliminate",body:"Functional managers own adherence; process owners own sustaining performance."}],final:"Belt develops the monitoring plan → answer **B**",whyWrong:["Incorrect — functional managers are responsible for adherence to the plan once it is running.","","Incorrect — process owners are accountable for sustaining performance, not for developing the plan alone.","Incorrect — a training department typically owns ongoing training, not the monitoring plan."],bookRef:"Book p. 568"},{id:"sv-5-1203",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which group does the training plan name as needing training because they are affected by the **control plan** itself?",options:["Only the operators who run the improved process each day","Only the project team members who designed the change","Process owners, managers and people who will change the process in the future","Only new employees at their orientation"],answer:2,hint:"The book splits 'impacted by the improvement' from 'impacted by the control plan'.",steps:[{title:"Key idea",body:"Those impacted by the control plan: process owners/managers, people who support the processes in the plan, and people who will make future changes."},{title:"Eliminate",body:"The other options name only part of the audience."}],final:"Owners, managers, future changers → answer **C**",whyWrong:["Incorrect — operators are trained because they are affected by the improvement; the control plan reaches further.","Incorrect — the project team delivers immediate training; it is not the audience named here.","","Incorrect — orientation is one trigger for ongoing training, not the full audience."],bookRef:"Book p. 565"},{id:"sv-5-1204",phase:5,topic:"5.3.2",qtype:"concept",difficulty:1,stem:"Which statement about the control plan is CORRECT?",options:["It replaces detailed maintenance and design instructions","It is fixed once signed off and is not updated","It is created by the Green Belt alone after the team disbands","It is an essential portion of the final project report"],answer:3,hint:"Recall the book's bullet list 'A Control Plan is…'.",steps:[{title:"Key idea",body:"The control plan is an ESSENTIAL portion of the final project report."},{title:"Eliminate",body:"Not a replacement for instructions, not static, not a solo task."}],final:"Essential part of the final report → answer **D**",whyWrong:["Incorrect — the book says it is NOT a replacement for detailed operating, maintenance or design instructions.","Incorrect — it is a living document, updated as new controls are added.","Incorrect — the project team and everyone with a role in the process create it.",""],bookRef:"Book pp. 562–563"},{id:"sv-5-1205",phase:5,topic:"5.3.2",qtype:"concept",difficulty:2,stem:"Which statement about the documentation plan is CORRECT?",options:["Documentation must be kept current to be useful","It is completed once at handoff and then archived","It covers process documents but not training manuals","It is owned by the customer after project closure"],answer:0,hint:"Out-of-date documents are worse than none.",steps:[{title:"Key idea",body:'The book: "Documentation must be kept current to be useful."'},{title:"Eliminate",body:"It is maintained, includes training manuals, and is owned internally."}],final:"Keep documentation current → answer **A**",whyWrong:["","Incorrect — the plan must name who updates and who reviews documents as the process changes.","Incorrect — training manuals are listed under control-plan documentation.","Incorrect — responsibility for ongoing documentation sits inside the organisation."],bookRef:"Book pp. 566–567"},{id:"sv-5-1206",phase:5,topic:"5.3.2",qtype:"concept",difficulty:3,stem:"Which statement about the five control-plan elements is CORRECT?",options:["The monitoring plan defines the incentive pay for the new behaviour","The response plan says what to do when monitoring shows a defect or out-of-control condition","The training plan lists the SOPs and process maps to be updated","Aligning systems and structures states what to sample and when"],answer:1,hint:"Match each element to its own content.",steps:[{title:"Key idea",body:"Response plan: the process to follow when there is a defect or an out-of-control signal from monitoring."},{title:"Eliminate",body:"Each wrong option swaps the content of two elements."}],final:"Response plan = what to do on a signal → answer **B**",whyWrong:["Incorrect — incentive pay belongs to aligning systems and structures.","","Incorrect — SOPs and process maps belong to the documentation plan.","Incorrect — sampling rules belong to the monitoring plan."],bookRef:"Book pp. 564, 571"},{id:"sv-5-1207",phase:5,topic:"5.3.2",qtype:"statements",difficulty:2,stem:`Consider these statements about the control plan:

1. It replaces the detailed operating instructions for the process.
2. It is a living document, updated as new controls are added.
3. It is a written summary of the monitoring and control methods.
4. It is created only by the Green Belt.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Living summary, not a replacement, made by many.",steps:[{title:"Key idea",body:"Control plan: written summary; living document; NOT a replacement for detailed instructions; created by the team and process stakeholders."},{title:"Apply",body:"Statements 2 and 3 are true."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: the control plan is NOT a replacement for detailed instructions.","","Incorrect — statement 4 is false: the project team and everyone with a role in the process create it.","Incorrect — both are false: it does not replace instructions and is not a solo Belt task."],bookRef:"Book pp. 562–563"},{id:"sv-5-1208",phase:5,topic:"5.3.2",qtype:"statements",difficulty:3,stem:`Consider these statements about the elements of a control plan:

1. A hypothesis test plan is one of the five elements.
2. The project charter is one of the five elements.
3. The training plan identifies who requires training.
4. The response plan is one of the five elements.

Which statements are CORRECT?`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Training, documentation, monitoring, response, aligning systems.",steps:[{title:"Key idea",body:"The five elements: documentation, monitoring, response, training, and aligning systems and structures."},{title:"Apply",body:"Statements 3 and 4 are true; 1 and 2 name earlier-phase documents."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — both are false: neither a hypothesis test plan nor the charter is a control-plan element.","Incorrect — statement 2 is false: the charter is a Define document, not a control-plan element.","","Incorrect — statement 1 is false: hypothesis tests belong to Analyze."],bookRef:"Book pp. 564–565"},{id:"sv-5-1209",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A control plan is a [?] document, updated as new measurement systems and control methods are added for continuous improvement.`,options:["controlled","final","living","static"],answer:2,hint:"It grows with the process.",steps:[{title:"Key idea",body:'Book: the control plan is a "living document to be updated as new measurement systems and control methods are added".'},{title:"Apply",body:"living."}],final:"living → answer **C**",whyWrong:["Incorrect — 'controlled' describes document management, not the book's term for the plan.","Incorrect — the plan is part of the final report but is never 'final'; it keeps changing.","","Incorrect — 'static' is the opposite of what the book describes."],bookRef:"Book p. 562"},{id:"sv-5-1210",phase:5,topic:"5.3.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

The book describes the control plan as the last [?] of the Control phase.`,options:["financial check","physical result","statistical test","tollgate review"],answer:1,hint:"It is the tangible output of the phase.",steps:[{title:"Key idea",body:'Book: "The last physical result of the Control Phase is the Control Plan."'},{title:"Apply",body:"physical result."}],final:"physical result → answer **B**",whyWrong:["Incorrect — verifying financial impact follows the plan, but the book calls the plan the last physical result.","","Incorrect — statistical tests confirm changes; the plan is a document, not a test.","Incorrect — a tollgate review is a governance meeting, not the book's description."],bookRef:"Book p. 556"},{id:"sv-5-1211",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:3,stem:"Which is NOT a reason the book gives for needing a control plan?",options:["It allows the Belt to move on to other projects","It makes people follow the designated control methods","It analyses and eliminates the potential X's","It is increasingly a customer requirement"],answer:2,hint:"The X's were found and proven before Control.",steps:[{title:"Key idea",body:"Why a control plan: sustain results, follow designated methods, let the Belt move on, prevent constant heroes, customer requirement."},{title:"Apply",body:"Analysing and eliminating X's is Analyze/Improve work, not a control-plan benefit."}],final:"Finding X's is not a control-plan purpose → answer **C**",whyWrong:["Incorrect — letting the Belt move on is a stated reason.","Incorrect — requiring operators, engineers and managers to follow control methods is a stated reason.","","Incorrect — the book notes control plans are becoming more of a customer requirement."],trap:"The control plan sustains controls on known X's; it does not discover them.",bookRef:"Book p. 563"},{id:"sv-5-1212",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:2,stem:"Who is NOT listed by the book among those who should help create the control plan?",options:["Associates who work in the process","Human Resources","Technical experts","The organisation's external auditors"],answer:3,hint:"Anyone with a role in defining, executing or changing the process.",steps:[{title:"Key idea",body:"Book list: the project team plus associates, technical experts, supervisors, managers, site manager and HR."},{title:"Apply",body:"External auditors have no role in defining, running or changing the process."}],final:"External auditors are not listed → answer **D**",whyWrong:["Incorrect — associates who execute the process are listed.","Incorrect — HR is listed, as job descriptions and incentives may change.","Incorrect — technical experts are listed.",""],bookRef:"Book p. 563"},{id:"sv-5-1213",phase:5,topic:"5.3.2",qtype:"not-except",difficulty:3,stem:"Which item is NOT named by the book as information used to develop the control plan?",options:["The Define-phase stakeholder analysis","Results from the Measure and Analyze phases","Lessons learned from similar products and processes","The defect prevention methods selected"],answer:0,hint:"Inputs: M and A results, lessons learned, team knowledge, DFMEAs, design reviews, selected methods.",steps:[{title:"Key idea",body:"Book inputs: Measure/Analyze results, lessons learned, team knowledge, design FMEAs, design reviews, defect prevention methods selected."},{title:"Apply",body:"The stakeholder analysis is a Define change-management tool, not a listed input."}],final:"Stakeholder analysis is not listed → answer **A**",whyWrong:["","Incorrect — Measure and Analyze results are a named input.","Incorrect — lessons learned from similar products and processes are a named input.","Incorrect — the selected defect prevention methods are a named input."],bookRef:"Book p. 564"},{id:"sv-5-1214",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"A draft control plan for SIM-swap checks lists the SPC chart, the sampling frequency and the OCAP. Nobody has decided who will teach the checks to new retail agents or when refresher sessions happen. Which element is incomplete?",options:["Documentation plan","Training plan","Monitoring plan","Response plan"],answer:1,hint:"Who, by whom and when — for people.",steps:[{title:"Key idea",body:"The training plan covers who needs training, who trains, the schedule, and triggers such as new-hire orientation and refreshers."},{title:"Apply",body:"New-agent and refresher training are missing → training plan."}],final:"Missing trainers and triggers = training plan → answer **B**",whyWrong:["Incorrect — documentation lists the documents to keep current, not who teaches whom.","","Incorrect — chart and sampling frequency, the monitoring content, are already in place.","Incorrect — the OCAP, the response content, is already in place."],bookRef:"Book p. 565"},{id:"sv-5-1215",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"Three months after a Green Belt is reassigned, an I chart of **dispatch time** fails Test 1. The supervisor knows the chart has signalled but nobody knows what to check or who should act. Which control-plan element was missing?",options:["Documentation plan","Monitoring plan","Response plan","Training plan"],answer:2,hint:"Detection worked; reaction did not.",steps:[{title:"Key idea",body:"The response plan sets out what to do, and who does it, when monitoring shows a defect or out-of-control condition."},{title:"Apply",body:"The signal was seen but no actions or roles were defined → response plan."}],final:"No defined reaction = response plan missing → answer **C**",whyWrong:["Incorrect — documents may exist; the gap is what to do when a signal appears.","Incorrect — monitoring worked: the chart detected the signal.","","Incorrect — training matters, but the missing content is the planned response itself."],bookRef:"Book pp. 564, 571"},{id:"sv-5-1216",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:1,stem:"At the Control tollgate, the sponsor asks what the final **tangible deliverable** of the phase is. What should the Green Belt answer?",options:["The project charter","The process capability baseline","The FMEA from Analyze","The control plan"],answer:3,hint:"The book names the last physical result of Control.",steps:[{title:"Key idea",body:"Book: the last physical result of the Control phase is the control plan."},{title:"Eliminate",body:"Charter, baseline and FMEA are earlier deliverables or inputs."}],final:"Control plan → answer **D**",whyWrong:["Incorrect — the charter is the Define deliverable that starts the project.","Incorrect — the baseline is set in Measure; final capability feeds the plan but is not the last result.","Incorrect — the FMEA is an input kept current inside the plan, not the final result.",""],bookRef:"Book p. 556"},{id:"sv-5-1217",phase:5,topic:"5.3.2",qtype:"scenario",difficulty:2,stem:"A Green Belt drafts the control plan for a repair-centre process alone at her desk. The technicians first see it at the go-live briefing and say several controls cannot work on the floor. Which Control-phase roadblock does this show?",options:["Team members are not involved in control plan design","Lack of project sign-off","Financial benefits are not tracked","Management lacks knowledge of monitoring needs"],answer:0,hint:"Who should have helped write it?",steps:[{title:"Key idea",body:'Book roadblocks include "Team members are not involved in Control Plan design"; the plan should be created by everyone with a role in the process.'},{title:"Apply",body:"Technicians saw it only at go-live → not involved."}],final:"Team not involved in design → answer **A**",whyWrong:["","Incorrect — sign-off is a separate step; the problem started with how the plan was drafted.","Incorrect — benefit tracking is unrelated to whether the controls work on the floor.","Incorrect — the gap here is the people who run the process, not management."],bookRef:"Book pp. 563, 577"},{id:"sv-5-1218",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:'After handoff, the process owner asks the Green Belt to keep reviewing the charts and responding to signals "until year end". The Belt agrees. Was this appropriate?',options:["Yes, because the Belt understands the charts best","Yes, because the Belt owns the control plan after closure","No, because the control plan should let the Belt move on while the owner sustains the gains","No, because control charts are no longer needed once the project closes"],answer:2,hint:"Who sustains, and who moves on?",steps:[{title:"Key idea",body:"A control plan allows a Belt to move on; process owners are accountable and functional managers own adherence to monitoring."},{title:"Apply",body:"Keeping the Belt in charge defeats the handoff → not appropriate."}],final:"Owner sustains; Belt moves on → answer **C**",whyWrong:["Incorrect — expertise is passed on through training; it does not make the Belt the owner.","Incorrect — process owners are accountable for maintaining the new performance level.","","Incorrect — charts continue under the monitoring plan after closure."],bookRef:"Book pp. 563–564, 568"},{id:"sv-5-1219",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:3,stem:"Six months after closure, a new automated data-quality check is added to the order-entry process with its own weekly chart. What is the FIRST action for the control plan?",options:["Leave the plan unchanged because it was signed off at closure","Update the control plan to include the new check and its monitoring","Write a new, separate control plan for the check","Remove the older controls to keep the plan short"],answer:1,hint:"Living document.",steps:[{title:"Key idea",body:"The control plan is updated as new measurement systems and control methods are added."},{title:"Apply",body:"Add the new check, its chart and owner to the existing plan first."}],final:"Update the living plan → answer **B**",whyWrong:["Incorrect — sign-off does not freeze the plan; it is a living document.","","Incorrect — the plan should formally record all control methods together, not split them.","Incorrect — removing working controls risks losing the gains."],bookRef:"Book p. 562"},{id:"sv-5-1220",phase:5,topic:"5.3.2",qtype:"best-action",difficulty:2,stem:"Before go-live, the Belt finds that the functional managers who will be responsible for adherence to the monitoring plan have never read a control chart. What is the BEST action?",options:["Have the Belt keep responsibility for adherence instead","Remove the control charts from the monitoring plan","Train the functional managers and make them accountable for adherence","Move adherence to the Finance department"],answer:2,hint:"The book attaches two conditions to managers' adherence role.",steps:[{title:"Key idea",body:"Book: functional managers are responsible for adherence — they must be trained on how to do this and made accountable."},{title:"Apply",body:"Close the skill gap with training and set accountability."}],final:"Train and hold managers accountable → answer **C**",whyWrong:["Incorrect — the Belt develops the plan; adherence belongs to functional managers.","Incorrect — dropping SPC weakens monitoring; the gap is skills, not the tool.","","Incorrect — Finance tracks benefits; it does not run process monitoring."],bookRef:"Book p. 568"},{id:"sv-5-1221",phase:5,topic:"5.3.2",qtype:"output",difficulty:1,stem:`A handoff status report for a billing-dispute process reads:

\`\`\`
Control plan element               Status
Training plan                      Complete
Documentation plan                 Complete
Monitoring plan                    Complete
Response plan                      Not started
Aligning systems and structures    Complete
\`\`\`

What is still missing before handoff?`,options:["Who needs training and when it will be delivered","Which documents must be kept current and who reviews them","When and how the process will be sampled and measured","What to do when monitoring shows a defect or out-of-control condition"],answer:3,hint:"Match the open element to its content.",steps:[{title:"Key idea",body:"The response plan outlines what to do when there is a defect or out-of-control signal from monitoring."},{title:"Apply",body:"Only the response plan is not started."}],final:"Response plan content is missing → answer **D**",whyWrong:["Incorrect — that is the training plan, shown as complete.","Incorrect — that is the documentation plan, shown as complete.","Incorrect — that is the monitoring plan, shown as complete.",""],bookRef:"Book pp. 564, 571"},{id:"sv-5-1222",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`Part of a training plan outline for a new fault-triage script is shown:

\`\`\`
Training module   Created by     Who is trained      Trainer       Integration into new-
                                                                   employee training
Triage script v2  Project team   Current NOC staff   Project team  (blank)
\`\`\`

Which gap does this outline show?`,options:["Ongoing training for future new employees has not been planned","The current staff have not been included in the training","Nobody has been named to create the training module","The project team cannot deliver any of the training"],answer:0,hint:"Look for the empty column.",steps:[{title:"Key idea",body:"The book's training plan outline includes integration into ongoing new-employee training; new-hire orientation is a trigger for ongoing training."},{title:"Apply",body:"That column is blank → future new hires would miss the script."}],final:"New-hire integration is blank → answer **A**",whyWrong:["","Incorrect — current NOC staff are listed as trainees.","Incorrect — the project team is named as creator.","Incorrect — the book says the project team typically conducts the immediate training."],bookRef:"Book pp. 565–566"},{id:"sv-5-1223",phase:5,topic:"5.3.2",qtype:"output",difficulty:3,stem:`A draft responsibility table for a control plan reads:

\`\`\`
Row  Activity                                      Assigned to
1    Develop the monitoring plan                   Green Belt, with team
2    Day-to-day adherence to the monitoring plan   Green Belt
3    Maintain the new level of performance         Training department
4    Deliver the immediate training on the change  Project team
\`\`\`

Which rows are consistent with the book?`,options:["Rows 1 and 2","Rows 2 and 3","Rows 3 and 4","Rows 1 and 4"],answer:3,hint:"Develop ≠ adhere ≠ sustain.",steps:[{title:"Key idea",body:"Belt develops monitoring (with team); functional managers adhere; process owners sustain performance; the project team delivers immediate training."},{title:"Apply",body:"Rows 1 and 4 match the book."}],final:"Rows 1 and 4 → answer **D**",whyWrong:["Incorrect — Row 2 is wrong: functional managers are responsible for adherence.","Incorrect — both are wrong: adherence sits with functional managers and sustaining performance with process owners.","Incorrect — Row 3 is wrong: process owners are accountable for the new performance level.",""],bookRef:"Book pp. 564–565, 568"},{id:"sv-5-1224",phase:5,topic:"5.3.2",qtype:"true-false",difficulty:1,stem:"According to the book, a control plan is NOT a replacement for the information in detailed operating, maintenance or design instructions. True or False?",options:["True","False"],answer:0,hint:"Summary versus detail.",steps:[{title:"Key idea",body:'Book: the control plan is "NOT a replacement of information contained in detailed operating, maintenance or design instructions".'},{title:"Apply",body:"The statement matches → True."}],final:"Not a replacement → True → answer **A**",whyWrong:["","Incorrect — the book states exactly this: the plan summarises controls and does not replace detailed instructions."],bookRef:"Book p. 562"},{id:"sv-5-1225",phase:5,topic:"5.3.2",qtype:"sequence",difficulty:2,stem:`Put these control-plan activities in a logical order:

- **P** — Supervisors and management of the area sign off the plan
- **Q** — The team develops the plan from Measure and Analyze results and the selected methods
- **R** — The plan is updated as new controls are added
- **S** — The plan is handed off to the process owner`,options:["P, Q, S, R","Q, P, S, R","Q, S, P, R","Q, P, R, S"],answer:1,hint:"Build → accept → hand over → keep alive.",steps:[{title:"Key idea",body:"Develop the plan from available information, secure sign-off from area supervisors and management, hand off to the process owner, then keep it living."},{title:"Apply",body:"Q, P, S, R."}],final:"Q, P, S, R → answer **B**",whyWrong:["Incorrect — the plan must be developed before it can be signed off.","","Incorrect — sign-off by the area secures acceptance before handoff to the owner.","Incorrect — updating as a living document continues after handoff, not before it."],bookRef:"Book pp. 562–564, 573"}];export{e as items};
